print('selfies_available', importlib.util.find_spec('selfies') is not None)
try:
 import selfies
 print('selfies_version', getattr(selfies,'__version__','unknown'))
 rxn='[C][N][Branch1][=Branch2][C][C][C][C][=Branch1][C][=O][O][C][=Branch1][C][=O][O][C][Branch1][C][C][Branch1][C][C][C].[N][C][=C][C][=C][C][Branch1][=Branch1][N+1][=Branch1][C][=O][O-1][=C][Ring1][=Branch2][N]>>[C][N][Branch2][Ring1][=Branch2][C][C][C][C][=Branch1][C][=O][N][C][=C][C][=C][C][Branch1][=Branch1][N+1][=Branch1][C][=O][O-1][=C][Ring1][=Branch2][N][C][=Branch1][C][=O][O][C][Branch1][C][C][Branch1][C][C][C]'
 for side,label in zip(rxn.split('>>'),['reactants','product']):
  print(label)
  for part in side.split('.'):
   try: print(selfies.decoder(part))
   except Exception as e: print('decode_error',type(e).__name__,str(e))
except Exception as e: print('import/decode_error',type(e).__name__,str(e))", 'language': 'python'}
